// The API reference is the one page on this origin that runs a script from
// another host, and it shares its origin with the admin. The version is
// pinned and the browser checks the bytes against this hash, so a changed
// file on the CDN does not run.
//
// The URL names a file the package publishes. The bare package URL and any
// .min.js the package does not ship are minified by jsDelivr on request, and
// a hash over generated bytes breaks the page when jsDelivr regenerates them.
// Update version and hash together:
//   curl -sL https://cdn.jsdelivr.net/npm/@scalar/api-reference@<version>/dist/browser/standalone.js \
//     | openssl dgst -sha384 -binary | openssl base64 -A
const SCALAR_VERSION = "1.53.1";
const SCALAR_FILE = "dist/browser/standalone.js";
const SCALAR_INTEGRITY = "sha384-gvOxOyq2boTO3Pm8IpXd8PMTZMIImRjqjBkaVH6hDTPHbG9vslCa+x9ogp0Pwho0";

const SCALAR_HTML = `<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>shrtnr API reference</title>
  </head>
  <body>
    <script
      id="api-reference"
      data-url="/_/api/openapi.json"
      data-configuration='{"theme":"deepSpace","layout":"modern"}'></script>
    <script
      src="https://cdn.jsdelivr.net/npm/@scalar/api-reference@${SCALAR_VERSION}/${SCALAR_FILE}"
      integrity="${SCALAR_INTEGRITY}"
      crossorigin="anonymous"></script>
  </body>
</html>`;

export function scalarResponse(): Response {
  return new Response(SCALAR_HTML, {
    status: 200,
    headers: {
      "Content-Type": "text/html; charset=utf-8",
      "Cache-Control": "no-store",
    },
  });
}
